<?php
declare(strict_types=1);
require_once __DIR__.'/lib/Harness.php';
foreach(['Routing','Features','Policy','Codec','Auth','Store','Cluster','Broker','Metadata','HttpMetadata']as$class)require_once dirname(__DIR__).'/src/'.$class.'.php';
function hmBroker():Broker{$dir=sys_get_temp_dir().'/qf-http-meta-test-'.bin2hex(random_bytes(6));$b=new Broker(new Store($dir.'/messages.log'),$dir.'/users.json');$b->bootstrap('devpassword12');return$b;}
function hmApply(Broker$b,array$stage):void{foreach($stage['commands']as$command)$b->applyRaft('meta',$command['kind'],$command['data'],0);}
function hmReject(Broker$b,string$method,string$path,array$json,string$label):void{$before=$b->raftState('meta');$thrown=false;try{HttpMetadata::stage($b,$method,$path,$json);}catch(RuntimeException){$thrown=true;}Harness::ok($label.' rejected',$thrown);Harness::eq($label.' leaves live metadata',$before,$b->raftState('meta'));}
Harness::guard('users passwords and vhosts stage without live mutations',static function():void{
 $b=hmBroker();$before=$b->raftState('meta');$stage=HttpMetadata::stage($b,'PUT','/api/users/alice',['password'=>'password123','tags'=>'management, monitoring']);Harness::eq('user stage live untouched',$before,$b->raftState('meta'));Harness::eq('hash command kind','user',$stage['commands'][0]['kind']);Harness::ok('password is hashed',Auth::matches('password123',$stage['commands'][0]['data']['hash']));Harness::ok('plaintext absent',!str_contains(json_encode($stage['commands']),'password123'));hmApply($b,$stage);Harness::ok('committed login',$b->verify('alice','password123'));
 $stage=HttpMetadata::stage($b,'PUT','/api/vhosts/tenant',[]);Harness::ok('vhost invisible before commit',!in_array('tenant',$b->vhosts,true));hmApply($b,$stage);Harness::ok('vhost committed',in_array('tenant',$b->vhosts,true));
 hmReject($b,'PUT','/api/users/weak',['password'=>'short'],'weak password');hmReject($b,'PUT','/api/users/badhash',['password_hash'=>'bad'],'bad hash');hmReject($b,'DELETE','/api/vhosts/%2f',[],'default vhost delete');
 $stage=HttpMetadata::stage($b,'PUT','/api/permissions/tenant/alice',['configure'=>'.*','write'=>'^events$','read'=>'.*']);hmApply($b,$stage);Harness::eq('permission canonical vhost','^events$',$b->permissions['alice']['tenant']['write']);hmReject($b,'PUT','/api/permissions/tenant/alice',['write'=>'['],'permission regex');hmReject($b,'PUT','/api/permissions/missing/alice',[],'missing permission vhost');
});
Harness::guard('queue exchange and binding use strict protocol metadata',static function():void{
 $b=hmBroker();$b->vhosts[]='tenant';$s=HttpMetadata::stage($b,'PUT','/api/queues/tenant/q',['durable'=>true,'arguments'=>['x-queue-type'=>'stream']]);Harness::ok('queue not live',!isset($b->forVhost('tenant')->queues['q']));hmApply($b,$s);Harness::eq('stream queue type','stream',$b->forVhost('tenant')->queues['q']['args']['queueType']);Harness::ok('root vhost isolated',!isset($b->queues['q']));
 hmReject($b,'PUT','/api/queues/tenant/q',['durable'=>true,'arguments'=>['x-queue-type'=>'classic']],'inequivalent queue');hmReject($b,'PUT','/api/queues/tenant/invalid',['arguments'=>['x-message-ttl'=>-1]],'negative ttl');hmReject($b,'PUT','/api/queues/tenant/transient',['durable'=>false,'arguments'=>['x-queue-type'=>'quorum']],'transient quorum');hmReject($b,'PUT','/api/queues/tenant/exclusive',['exclusive'=>true],'exclusive management');
 $s=HttpMetadata::stage($b,'PUT','/api/exchanges/tenant/events',['type'=>'topic','durable'=>true]);hmApply($b,$s);$s=HttpMetadata::stage($b,'POST','/api/bindings/tenant/e/events/q/q',['routing_key'=>'key.#']);Harness::eq('binding not yet live',0,count($b->forVhost('tenant')->bindings));hmApply($b,$s);Harness::eq('binding committed','key.#',$b->forVhost('tenant')->bindings[0]['key']);hmReject($b,'PUT','/api/exchanges/tenant/events',['type'=>'direct'],'inequivalent exchange');hmReject($b,'POST','/api/bindings/tenant/e/missing/q/q',[],'missing binding source');
 $s=HttpMetadata::stage($b,'DELETE','/api/bindings/tenant/e/events/q/q/key.%23',[]);hmApply($b,$s);Harness::eq('binding delete committed',[],$b->forVhost('tenant')->bindings);
 $s=HttpMetadata::stage($b,'DELETE','/api/queues/tenant/q',[]);hmApply($b,$s);Harness::ok('queue delete committed',!isset($b->forVhost('tenant')->queues['q']));
